package com.campusbite.orders;
import com.campusbite.users.*; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/orders") public class OrderController {
 private final OrderService service; private final UserRepository users; public OrderController(OrderService s,UserRepository u){service=s;users=u;}
 @PostMapping @PreAuthorize("hasRole('CUSTOMER')") public OrderView create(@Valid @RequestBody CreateOrderRequest r,Authentication a){return service.create(a.getName(),r);}
 @GetMapping("/my") @PreAuthorize("hasRole('CUSTOMER')") public List<OrderView> mine(Authentication a){return service.myOrders(a.getName());}
 @GetMapping("/board") @PreAuthorize("hasAnyRole('CUSTOMER','STAFF','ADMIN','OWNER')") public List<QueueEntry> board(@RequestParam String outlet,Authentication a){return service.board(outlet,a.getName());}
 @GetMapping("/queue") @PreAuthorize("hasAnyRole('STAFF','ADMIN','OWNER')") public List<OrderView> queue(@RequestParam String outlet,Authentication a){AppUser u=users.findByEmail(a.getName()).orElseThrow(); if(u.getRole()==Role.STAFF)return service.queueForStaff(outlet,u.getAssignedOutlet()); return service.queue(outlet);}
 @GetMapping @PreAuthorize("hasAnyRole('ADMIN','OWNER')") public List<OrderView> all(){return service.allOrders();}
 @GetMapping("/{id}") @PreAuthorize("hasAnyRole('CUSTOMER','STAFF','ADMIN','OWNER')") public OrderView get(@PathVariable String id,Authentication a){AppUser u=users.findByEmail(a.getName()).orElseThrow(); boolean privileged=u.getRole()!=Role.CUSTOMER; OrderView v=service.get(id,a.getName(),privileged); if(u.getRole()==Role.STAFF&&(u.getAssignedOutlet()==null||!u.getAssignedOutlet().equalsIgnoreCase(v.order().getOutlet()))) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Outside your assigned outlet"); return v;}
 @PatchMapping("/{id}/status") @PreAuthorize("hasAnyRole('STAFF','ADMIN','OWNER')") public OrderView status(@PathVariable String id,@RequestParam OrderStatus status,Authentication a){AppUser u=users.findByEmail(a.getName()).orElseThrow(); return u.getRole()==Role.STAFF?service.updateStatusForStaff(id,status,u.getAssignedOutlet()):service.updateStatus(id,status);}
 @PatchMapping("/{id}/payment/paid") @PreAuthorize("hasAnyRole('STAFF','ADMIN','OWNER')") public OrderView markPaid(@PathVariable String id,Authentication a){AppUser u=users.findByEmail(a.getName()).orElseThrow(); if(u.getRole()==Role.STAFF&&(u.getAssignedOutlet()==null||u.getAssignedOutlet().isBlank()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Staff account has no assigned outlet"); return service.markPaymentPaid(id,u.getRole()==Role.STAFF?u.getAssignedOutlet():null);}
 @PatchMapping("/{id}/cancel") @PreAuthorize("hasRole('CUSTOMER')") public OrderView cancel(@PathVariable String id,Authentication a){return service.cancelOwn(id,a.getName());}
 @PatchMapping("/{id}/collected") @PreAuthorize("hasRole('CUSTOMER')") public OrderView collected(@PathVariable String id,Authentication a){return service.markCollected(id,a.getName());}
}
